#include <pigpio.h>

int main() {
  // Initialize the pigpio library
  if (gpioInitialise() < 0) {
    std::cerr << "pigpio initialization failed" << std::endl;
    return 1;
  }

  // Set the mode of GPIO pin 12 to OUTPUT
  gpioSetup(12, PI_OUTPUT);

  // Set the initial state of GPIO pin 12 to LOW
  gpioWrite(12, PI_LOW);

  while (true) {
    // Read the current state of GPIO pin 12
    int state = gpioRead(12);

    // Toggle the state of GPIO pin 12
    gpioWrite(12, state ? PI_HIGH : PI_LOW);
    delay(1000); // wait 1 second

    // Read the current state of GPIO pin 12
    state = gpioRead(12);

    // Print the state of GPIO pin 12
    std::cout << "GPIO pin 12 state: " << (state ? "HIGH" : "LOW") << std::endl;
    delay(1000); // wait 1 second
  }

  // Clean up
  gpioTerminate();
  return 0;
}
